CREATE TABLE IF NOT EXISTS learn_courses(id INTEGER PRIMARY KEY AUTOINCREMENT,course_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',locale TEXT NOT NULL DEFAULT 'fa',status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_chapters(id INTEGER PRIMARY KEY AUTOINCREMENT,course_id INTEGER NOT NULL REFERENCES learn_courses(id) ON DELETE CASCADE,title TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_lessons(id INTEGER PRIMARY KEY AUTOINCREMENT,chapter_id INTEGER NOT NULL REFERENCES learn_chapters(id) ON DELETE CASCADE,lesson_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',block_document TEXT NOT NULL DEFAULT '',block_schema_version INTEGER NOT NULL DEFAULT 1,position INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_instructors(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,display_name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS learn_students(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_enrollments(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id INTEGER NOT NULL REFERENCES learn_students(id) ON DELETE CASCADE,course_id INTEGER NOT NULL REFERENCES learn_courses(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','completed','cancelled')),enrolled_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,course_id));
CREATE TABLE IF NOT EXISTS learn_progress(enrollment_id INTEGER NOT NULL REFERENCES learn_enrollments(id) ON DELETE CASCADE,lesson_id INTEGER NOT NULL REFERENCES learn_lessons(id) ON DELETE CASCADE,completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1)),progress_percent INTEGER NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(enrollment_id,lesson_id));
CREATE TABLE IF NOT EXISTS learn_quizzes(id INTEGER PRIMARY KEY AUTOINCREMENT,lesson_id INTEGER NOT NULL REFERENCES learn_lessons(id) ON DELETE CASCADE,title TEXT NOT NULL,config_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS learn_assignments(id INTEGER PRIMARY KEY AUTOINCREMENT,lesson_id INTEGER NOT NULL REFERENCES learn_lessons(id) ON DELETE CASCADE,title TEXT NOT NULL,instructions TEXT NOT NULL DEFAULT '',due_days INTEGER);
CREATE TABLE IF NOT EXISTS learn_certificates(id INTEGER PRIMARY KEY AUTOINCREMENT,enrollment_id INTEGER NOT NULL UNIQUE REFERENCES learn_enrollments(id) ON DELETE CASCADE,certificate_code TEXT NOT NULL UNIQUE,issued_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.16.0');